.pragma library

// Pure layout helpers for the drawer. No QML types here so the logic can be
// exercised outside the shell (see test/model.test.js).

var SECTIONS = ["left", "center", "right"]

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value)
}

function entryId(entry) {
  if (typeof entry === "string") return entry
  if (isPlainObject(entry) && entry.id !== undefined && entry.id !== null) return String(entry.id)
  return ""
}

function entrySettings(entry) {
  var out = {}
  if (!isPlainObject(entry)) return out
  for (var key in entry) if (key !== "id") out[key] = entry[key]
  return out
}

// `items` on a drawer entry may be a list of ids or a single id string.
function itemList(entry, drawerId) {
  var raw = isPlainObject(entry) ? entry.items : null
  if (typeof raw === "string") raw = [raw]
  if (!Array.isArray(raw)) return []
  var out = []
  for (var i = 0; i < raw.length; i++) {
    var id = entryId(raw[i]).trim()
    if (!id || id === drawerId || out.indexOf(id) !== -1) continue
    out.push(id)
  }
  return out
}

// Every widget id tucked by any drawer entry in the layout.
function tuckedIds(layout, drawerId) {
  var out = []
  if (!isPlainObject(layout)) return out
  for (var s = 0; s < SECTIONS.length; s++) {
    var entries = layout[SECTIONS[s]]
    if (!Array.isArray(entries)) continue
    for (var i = 0; i < entries.length; i++) {
      if (entryId(entries[i]) !== drawerId) continue
      var items = itemList(entries[i], drawerId)
      for (var j = 0; j < items.length; j++) if (out.indexOf(items[j]) === -1) out.push(items[j])
    }
  }
  return out
}

// Copy of the bar config with tucked widgets removed from the visible layout.
// Their entries stay in shell.json, so their settings keep persisting.
function filteredBarConfig(barConfig, drawerId) {
  var config = isPlainObject(barConfig) ? JSON.parse(JSON.stringify(barConfig)) : {}
  var layout = isPlainObject(config.layout) ? config.layout : null
  if (!layout) return config
  var tucked = tuckedIds(layout, drawerId)
  if (tucked.length === 0) return config
  for (var s = 0; s < SECTIONS.length; s++) {
    var entries = layout[SECTIONS[s]]
    if (!Array.isArray(entries)) continue
    layout[SECTIONS[s]] = entries.filter(function(entry) {
      return tucked.indexOf(entryId(entry)) === -1
    })
  }
  return config
}

// The widgets one drawer should host, in the order listed in `items`. Each
// widget's settings come from its own entry in bar.layout; a widget listed in
// `items` but absent from the layout gets empty settings.
function drawerItems(layout, drawerEntry, drawerId) {
  var items = itemList(drawerEntry, drawerId)
  var out = []
  for (var i = 0; i < items.length; i++) {
    var found = null
    if (isPlainObject(layout)) {
      for (var s = 0; s < SECTIONS.length && !found; s++) {
        var entries = layout[SECTIONS[s]]
        if (!Array.isArray(entries)) continue
        for (var j = 0; j < entries.length; j++) {
          if (entryId(entries[j]) === items[i]) {
            found = { id: items[i], region: SECTIONS[s], settings: entrySettings(entries[j]), inLayout: true }
            break
          }
        }
      }
    }
    out.push(found || { id: items[i], region: "drawer", settings: {}, inLayout: false })
  }
  return out
}

// The drawer entry for a given button's settings. The bar injects settings
// without the id, so rebuild the entry shape the helpers expect.
function entryFromSettings(drawerId, settings) {
  var entry = { id: drawerId }
  if (isPlainObject(settings)) for (var key in settings) entry[key] = settings[key]
  return entry
}

import QtQuick
import Quickshell
import Quickshell.Hyprland
import "DrawerModel.js" as DrawerModel

// Full-bar plugin that wraps the stock Omarchy bar instead of copying it.
//
// The stock Bar.qml is loaded unmodified from $OMARCHY_PATH, so bar updates
// keep flowing in. This wrapper only:
//   - hides widgets listed in a drawer's `items` from the visible layout,
//   - registers the drawer button (DrawerButton.qml) with the bar so it is
//     handed the live bar object and the widget catalogue, which a plain
//     third-party bar widget never receives,
//   - routes shell IPC (summon/hide/toggle) for tucked widgets into the drawer.
Item {
  id: root

  // Injected by the omarchy-shell host (see shell.qml configureBar()).
  property string omarchyPath: Quickshell.env("OMARCHY_PATH")
  property var shell: null
  property var manifest: null
  property var barWidgetRegistry: null
  property var pluginRegistry: null
  property var barConfig: ({})

  readonly property string drawerId: manifest && manifest.id ? String(manifest.id) : "parker.drawer"
  readonly property string upstreamBarUrl: "file://" + (omarchyPath || "/usr/share/omarchy") + "/shell/plugins/bar/Bar.qml"
  readonly property var innerBar: barLoader.item

  // Unfiltered layout, read by drawer buttons to find tucked entries' settings.
  readonly property var fullLayout: barConfig && barConfig.layout ? barConfig.layout : ({})
  readonly property var tucked: DrawerModel.tuckedIds(fullLayout, drawerId)
  readonly property var innerBarConfig: DrawerModel.filteredBarConfig(barConfig, drawerId)

  // Scalar state the host reads straight off shell.bar.
  readonly property bool barHidden: innerBar ? innerBar.barHidden === true : false
  readonly property int barSize: innerBar ? innerBar.barSize : 0
  readonly property string fontFamily: innerBar ? String(innerBar.fontFamily || "") : ""
  readonly property string position: innerBar ? String(innerBar.position || "top") : "top"

  // Live drawer buttons (one per monitor), registered by DrawerButton.qml.
  property var drawers: []

  function registerDrawer(drawer) {
    if (!drawer || drawers.indexOf(drawer) !== -1) return
    var next = drawers.slice()
    next.push(drawer)
    drawers = next
  }

  function unregisterDrawer(drawer) {
    drawers = drawers.filter(function(d) { return d !== drawer })
  }

  // Widget catalogue handed to the stock bar: the host snapshot plus the
  // drawer button, flagged first-party so the bar injects itself as `bar`.
  QtObject {
    id: drawerRegistry

    readonly property var drawerHost: root
    readonly property int revision: root.barWidgetRegistry ? root.barWidgetRegistry.revision : 0
    readonly property var widgets: {
      var source = root.barWidgetRegistry ? root.barWidgetRegistry.widgets : null
      var next = ({})
      if (source) for (var id in source) next[id] = source[id]
      var base = next[root.drawerId] && next[root.drawerId].metadata ? next[root.drawerId].metadata : ({})
      var meta = ({})
      for (var key in base) meta[key] = base[key]
      meta.firstParty = true
      meta.displayName = meta.displayName || "Drawer"
      next[root.drawerId] = { component: drawerButtonComponent, metadata: meta }
      return next
    }

    function metadataFor(id) {
      var entry = widgets[String(id || "")]
      return entry ? entry.metadata : null
    }

    function availableIds() { return Object.keys(widgets) }
    function has(id) { return widgets[String(id || "")] !== undefined }
  }

  Component {
    id: drawerButtonComponent
    DrawerButton { }
  }

  Loader {
    id: barLoader
    source: root.upstreamBarUrl

    onLoaded: {
      item.omarchyPath = Qt.binding(function() { return root.omarchyPath })
      item.manifest = Qt.binding(function() { return root.manifest })
      item.pluginRegistry = Qt.binding(function() { return root.pluginRegistry })
      item.shell = Qt.binding(function() { return root.shell })
      item.barWidgetRegistry = drawerRegistry
      item.barConfig = Qt.binding(function() { return root.innerBarConfig })
    }

    onStatusChanged: {
      if (status !== Loader.Error) return
      // Without the stock bar there is no bar at all. Hand control back to
      // the built-in bar rather than leave the user with an empty screen.
      console.warn("parker.drawer: could not load " + root.upstreamBarUrl + "; switching back to omarchy.bar")
      if (root.shell && typeof root.shell.mutateShellConfig === "function") {
        root.shell.mutateShellConfig(function(config) {
          if (config.bar && typeof config.bar === "object") config.bar.id = "omarchy.bar"
        })
      }
      Quickshell.execDetached(["notify-send", "Bar drawer",
        "Could not load the stock bar, switched back to omarchy.bar. See the shell log."])
    }
  }

  // ---------------------------------------------------------- host surface

  function isTucked(id) {
    return root.tucked.indexOf(String(id || "")) !== -1
  }

  function focusedDrawerFor(id) {
    var monitor = Hyprland.focusedMonitor
    var screenName = monitor ? String(monitor.name || "") : ""
    var fallback = null
    for (var i = 0; i < drawers.length; i++) {
      var drawer = drawers[i]
      if (!drawer || !drawer.hostsWidget(id)) continue
      if (!fallback) fallback = drawer
      if (screenName && drawer.screenName() === screenName) return drawer
    }
    return fallback
  }

  function summonBarWidget(id) {
    if (isTucked(id)) {
      var drawer = focusedDrawerFor(id)
      return drawer ? drawer.summonWidget(String(id)) : false
    }
    return innerBar ? innerBar.summonBarWidget(id) : false
  }

  function hideBarWidget(id) {
    if (isTucked(id)) {
      var hidden = false
      for (var i = 0; i < drawers.length; i++) if (drawers[i].hideWidget(String(id))) hidden = true
      return hidden
    }
    return innerBar ? innerBar.hideBarWidget(id) : false
  }

  function isBarWidgetOpen(id) {
    if (isTucked(id)) {
      for (var i = 0; i < drawers.length; i++) if (drawers[i].widgetOpen(String(id))) return true
      return false
    }
    return innerBar ? innerBar.isBarWidgetOpen(id) : false
  }

  function panelWidgetIdAt(section, index) {
    return innerBar ? innerBar.panelWidgetIdAt(section, index) : ""
  }

  function toggleTransparency() {
    if (innerBar) innerBar.toggleTransparency()
  }

  function debugBarGeometry() {
    return innerBar ? innerBar.debugBarGeometry() : []
  }

  // `omarchy-shell shell call parker.drawer toggleDrawer ""` style helper:
  // toggles the drawer on the focused monitor.
  function toggleDrawer() {
    var monitor = Hyprland.focusedMonitor
    var screenName = monitor ? String(monitor.name || "") : ""
    var target = null
    for (var i = 0; i < drawers.length; i++) {
      if (!target) target = drawers[i]
      if (screenName && drawers[i].screenName() === screenName) { target = drawers[i]; break }
    }
    if (target) target.toggle()
    return !!target
  }
}

import QtQuick
import Quickshell
import Quickshell.Hyprland
import qs.Commons
import qs.Ui
import "DrawerModel.js" as DrawerModel

// The drawer button. Clicking it opens a panel holding the widgets listed in
// this entry's `items`. Only works under the parker.drawer bar, which hands
// this widget the live bar object plus the drawer host; on any other bar it
// renders nothing.
BarWidget {
  id: root

  // `bar` is the stock Bar instance (we are flagged first-party by the
  // drawer bar's registry), so its widget catalogue is the drawer registry.
  readonly property var registry: bar && bar.barWidgetRegistry ? bar.barWidgetRegistry : null
  readonly property var host: registry && registry.drawerHost ? registry.drawerHost : null
  readonly property string drawerId: host ? host.drawerId : moduleName
  readonly property var items: host
    ? DrawerModel.drawerItems(host.fullLayout, DrawerModel.entryFromSettings(drawerId, settings), drawerId)
    : []

  property bool drawerOpen: false
  property var slotItems: []

  visible: host !== null
  implicitWidth: button.implicitWidth
  implicitHeight: button.implicitHeight

  onHostChanged: if (host) host.registerDrawer(root)
  Component.onCompleted: if (host) host.registerDrawer(root)
  Component.onDestruction: {
    if (host) host.unregisterDrawer(root)
    if (bar) for (var i = 0; i < slotItems.length; i++) bar.unregisterModuleSlot(slotItems[i])
  }

  // ------------------------------------------------------------ lifecycle

  function open() {
    if (drawerOpen) return
    // One popup at a time: opening the drawer closes any other bar panel.
    var other = bar ? bar.activePopout : null
    if (other && !ownsObject(other) && typeof other.close === "function") other.close()
    drawerOpen = true
  }

  function close() {
    if (!drawerOpen) return
    // A tucked widget's popup is anchored to the drawer; close it first.
    var active = bar ? bar.activePopout : null
    if (active && ownsObject(active) && typeof active.close === "function") active.close()
    drawerOpen = false
  }

  function toggle() { drawerOpen ? close() : open() }

  function screenName() {
    var window = root.QsWindow ? root.QsWindow.window : null
    return window && window.screen ? String(window.screen.name || "") : ""
  }

  // --------------------------------------------- IPC routing (via the host)

  function slotFor(id) {
    for (var i = 0; i < slotItems.length; i++)
      if (slotItems[i].moduleName === id && slotItems[i].activeItem) return slotItems[i]
    return null
  }

  function hostsWidget(id) { return slotFor(id) !== null }

  function panelCapable(item) {
    return item && typeof item.open === "function" && typeof item.close === "function" && item.opened !== undefined
  }

  function summonWidget(id) {
    var slot = slotFor(id)
    if (!slot || !panelCapable(slot.activeItem)) return false
    open()
    pendingSummon = id
    summonTimer.restart()
    return true
  }

  function hideWidget(id) {
    var slot = slotFor(id)
    if (!slot || !panelCapable(slot.activeItem) || slot.activeItem.opened !== true) return false
    slot.activeItem.close()
    return true
  }

  function widgetOpen(id) {
    var slot = slotFor(id)
    return !!slot && panelCapable(slot.activeItem) && slot.activeItem.opened === true
  }

  property string pendingSummon: ""

  // The tucked widget's popup anchors to the drawer window, which has to be
  // mapped first.
  Timer {
    id: summonTimer
    interval: 80
    onTriggered: {
      var slot = root.slotFor(root.pendingSummon)
      root.pendingSummon = ""
      if (slot && root.panelCapable(slot.activeItem)) slot.activeItem.open()
    }
  }

  // ------------------------------------------------- popout coordination

  // True when `target` lives inside the drawer (a tucked widget, its panel,
  // or a popup anchored to the drawer window).
  function ownsObject(target) {
    if (!target) return false
    var node = target
    for (var depth = 0; node && depth < 64; depth++) {
      if (node === content) return true
      node = node.parent
    }
    if (target.anchorItem && ownsObject(target.anchorItem)) return true
    if (target.anchor && target.anchor.window === drawerWindow) return true
    return false
  }

  readonly property bool childPopoutOpen: drawerOpen && bar !== null && bar.activePopout !== null
    && ownsObject(bar.activePopout)

  Connections {
    target: root.bar
    ignoreUnknownSignals: true
    function onActivePopoutChanged() {
      // Another bar widget opened its panel: get out of the way.
      var active = root.bar.activePopout
      if (root.drawerOpen && active && !root.ownsObject(active)) root.drawerOpen = false
    }
  }

  // ---------------------------------------------------------------- button

  BarIconButton {
    id: button
    anchors.fill: parent
    bar: root.bar
    text: root.drawerOpen ? String(root.setting("iconOpen", "\uf077")) : String(root.setting("icon", "\uf078"))
    tooltipText: root.drawerOpen ? "" : String(root.setting("tooltip", "More widgets"))
    onPressed: function(b) { if (b === Qt.LeftButton) root.toggle() }
  }

  Rectangle {
    // Same open-panel mark the bar draws under a widget whose panel is open.
    readonly property int inset: Style.space(2)
    visible: root.drawerOpen
    color: Color.accent
    opacity: 0.9
    radius: Math.min(width, height) / 2
    width: root.vertical ? Style.space(2) : Math.max(Style.space(10), Math.round(root.width * 0.55))
    height: root.vertical ? Math.max(Style.space(10), Math.round(root.height * 0.55)) : Style.space(2)
    x: root.vertical
      ? (root.bar && root.bar.position === "left" ? root.width - width - inset : inset)
      : Math.round((root.width - width) / 2)
    y: root.vertical
      ? Math.round((root.height - height) / 2)
      : (root.bar && root.bar.position === "top" ? root.height - height - inset : inset)
  }

  // ----------------------------------------------------------------- panel

  // Tucked widgets stay alive while the drawer is closed, so their timers,
  // IPC handlers and refreshes keep running exactly as they would on the bar.
  PopupWindow {
    id: drawerWindow

    readonly property int margin: Style.gapsOut
    readonly property int pad: Style.space(4)
    readonly property string barPosition: root.bar ? root.bar.position : "top"

    visible: root.drawerOpen && root.host !== null
    color: "transparent"
    implicitWidth: Math.max(Style.space(40), Math.ceil(content.implicitWidth + pad * 2 + 2))
    implicitHeight: Math.max(root.barSize, Math.ceil(content.implicitHeight + pad * 2 + 2))

    anchor {
      id: drawerAnchor
      window: root.QsWindow ? root.QsWindow.window : null
      adjustment: PopupAdjustment.Slide
      edges: Edges.Top | Edges.Left
      gravity: Edges.Bottom | Edges.Right
      rect.width: 1
      rect.height: 1

      onAnchoring: {
        var window = root.QsWindow ? root.QsWindow.window : null
        if (!window) return
        var w = drawerWindow.implicitWidth
        var h = drawerWindow.implicitHeight
        var m = drawerWindow.margin
        var localX = root.width / 2 - w / 2
        var localY = root.height + m
        if (drawerWindow.barPosition === "bottom") localY = -h - m
        else if (drawerWindow.barPosition === "left") { localX = root.width + m; localY = root.height / 2 - h / 2 }
        else if (drawerWindow.barPosition === "right") { localX = -w - m; localY = root.height / 2 - h / 2 }
        var point = window.contentItem.mapFromItem(root, localX, localY)
        drawerAnchor.rect.x = Math.round(point.x)
        drawerAnchor.rect.y = Math.round(point.y)
      }
    }

    // Click outside the drawer (and the bar) closes it. While a tucked
    // widget's own popup is open, that popup holds the grab instead.
    HyprlandFocusGrab {
      active: drawerWindow.visible && !root.childPopoutOpen
      windows: drawerAnchor.window ? [drawerWindow, drawerAnchor.window] : [drawerWindow]
      onCleared: Qt.callLater(function() { if (!root.childPopoutOpen) root.close() })
    }

    BorderSurface {
      anchors.fill: parent
      color: Color.bar.background
      borderSpec: Border.localOrSurfaceSpec("popups", "border", Color.popups.border, Color.popups.border, Math.max(1, Style.space(2)))
      radius: Style.cornerRadius
    }

    Text {
      anchors.centerIn: parent
      visible: content.implicitWidth <= 0 || content.implicitHeight <= 0
      text: root.items.length === 0 ? "No widgets in drawer" : "Nothing to show"
      color: Color.bar.text
      opacity: 0.6
      font.family: root.bar ? root.bar.fontFamily : Style.font.family
      font.pixelSize: Style.font.body
    }

    Grid {
      id: content
      x: drawerWindow.pad + 1
      y: drawerWindow.pad + 1
      flow: root.vertical ? Grid.TopToBottom : Grid.LeftToRight
      rows: root.vertical ? -1 : 1
      columns: root.vertical ? 1 : -1
      spacing: 0

      Repeater {
        model: root.items

        DrawerSlot {
          required property var modelData
          entry: modelData
        }
      }
    }
  }

  // One tucked widget. Mirrors how the stock bar's ModuleSlot loads and
  // injects a widget, and registers a zero-size proxy with the bar so
  // broadcast(), hotkeys and third-party facade bookkeeping see it.
  component DrawerSlot: Item {
    id: slot

    required property var entry
    readonly property string moduleName: entry.id
    readonly property var metadata: root.registry ? root.registry.metadataFor(moduleName) : null
    readonly property bool firstParty: !!metadata && metadata.firstParty === true
    readonly property var component: {
      var w = root.registry ? root.registry.widgets : null
      return w && w[moduleName] && moduleName !== root.drawerId ? w[moduleName].component : null
    }
    readonly property var activeItem: loader.item

    implicitWidth: activeItem && activeItem.visible ? (root.vertical ? root.barSize : activeItem.implicitWidth) : 0
    implicitHeight: activeItem && activeItem.visible ? activeItem.implicitHeight : 0
    width: implicitWidth
    height: implicitHeight

    Loader {
      id: loader
      anchors.fill: parent
      active: slot.component !== null
      sourceComponent: slot.component
      onLoaded: {
        slot.injectProps()
        Qt.callLater(slot.injectProps)
      }
    }

    onEntryChanged: injectProps()

    function injectProps() {
      var target = loader.item
      if (!target || !root.bar) return
      if ("bar" in target) target.bar = slot.firstParty
        ? root.bar : root.bar.pluginBarApiFor(slot.moduleName, slot.moduleName, true)
      if ("moduleName" in target) target.moduleName = slot.moduleName
      if ("settings" in target) target.settings = slot.entry.settings
    }

    // Invisible, zero-size stand-in registered in the bar's slot list. Zero
    // size keeps it out of drag-and-drop targeting; `region` is the widget's
    // real layout section so nothing ever writes a bogus section.
    Item {
      id: proxy
      visible: false
      width: 0
      height: 0
      readonly property string moduleName: slot.moduleName
      readonly property string region: slot.entry.region
      readonly property var entry: ({ id: slot.moduleName })
      readonly property var activeItem: slot.activeItem
      readonly property string pluginApiId: slot.firstParty ? slot.moduleName : slot.moduleName
      readonly property bool hovered: false
      readonly property bool dragSource: false
      readonly property bool panelOpen: false

      Component.onCompleted: root.addSlot(proxy)
      Component.onDestruction: root.removeSlot(proxy)
    }
  }

  function addSlot(proxy) {
    if (!bar || slotItems.indexOf(proxy) !== -1) return
    var next = slotItems.slice()
    next.push(proxy)
    slotItems = next
    bar.registerModuleSlot(proxy)
  }

  function removeSlot(proxy) {
    slotItems = slotItems.filter(function(s) { return s !== proxy })
    if (bar) bar.unregisterModuleSlot(proxy)
  }
}

