mkdir -p test && cat > test/model.test.js <<'EOF'
// Run: node test/model.test.js   (from the plugin directory)
const fs = require("fs"), path = require("path"), assert = require("assert")
const src = fs.readFileSync(path.join(__dirname, "..", "DrawerModel.js"), "utf8").replace(".pragma library", "")
const M = new Function(src + "; return { tuckedIds, filteredBarConfig, drawerItems, entryFromSettings, itemList }")()
const shell = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "..", "..", "shell.json"), "utf8"))
const id = "parker.drawer", bar = shell.bar
const tucked = M.tuckedIds(bar.layout, id)
const filtered = M.filteredBarConfig(bar, id)
const visible = s => filtered.layout[s].map(e => e.id)
for (const s of ["left", "center", "right"]) for (const t of tucked) assert(!visible(s).includes(t), t + " still on bar")
assert(visible("right").includes(id), "drawer button must stay on the bar")
assert.deepStrictEqual(bar.layout.right.length, 8, "real config must not be mutated")
const drawerEntry = bar.layout.right.find(e => e.id === id)
const settings = Object.fromEntries(Object.entries(drawerEntry).filter(([k]) => k !== "id"))
const items = M.drawerItems(bar.layout, M.entryFromSettings(id, settings), id)
assert.deepStrictEqual(items.map(i => i.id), drawerEntry.items)
assert(items.every(i => i.inLayout), "every tucked widget should keep its layout entry")
// edge cases
assert.deepStrictEqual(M.itemList({ items: "omarchy.clock" }, id), ["omarchy.clock"])
assert.deepStrictEqual(M.itemList({ items: [id, "a", "a", "", { id: "b" }] }, id), ["a", "b"])
assert.deepStrictEqual(M.itemList({}, id), [])
const clock = M.drawerItems({ center: [{ id: "omarchy.clock", format: "HH:mm" }] }, { items: ["omarchy.clock", "x.missing"] }, id)
assert.deepStrictEqual(clock[0], { id: "omarchy.clock", region: "center", settings: { format: "HH:mm" }, inLayout: true })
assert.strictEqual(clock[1].inLayout, false)
assert.deepStrictEqual(M.filteredBarConfig({ position: "top" }, id), { position: "top" })
console.log("visible:", JSON.stringify({ left: visible("left"), center: visible("center"), right: visible("right") }))
console.log("drawer:", items.map(i => i.id + "@" + i.region).join(", "))
console.log("model tests passed")
EOF
node test/model.test.js

cd .config/omarchy/plugins/parker.drawer && rm test/model.test.js && cat > test/ModelTest.qml <<'EOF'
// Run from the plugin directory:
//   QT_QPA_PLATFORM=offscreen qml6 test/ModelTest.qml
import QtQuick
import "../DrawerModel.js" as M

QtObject {
  function check(cond, msg) { if (!cond) throw new Error("FAIL: " + msg) }
  function same(a, b, msg) { check(JSON.stringify(a) === JSON.stringify(b), msg + " got " + JSON.stringify(a)) }

  Component.onCompleted: {
    var xhr = new XMLHttpRequest()
    xhr.open("GET", Qt.resolvedUrl("../../../shell.json"), false)
    xhr.send()
    var bar = JSON.parse(xhr.responseText).bar
    var id = "parker.drawer"
    var before = JSON.stringify(bar)
    var tucked = M.tuckedIds(bar.layout, id)
    var filtered = M.filteredBarConfig(bar, id)
    var vis = function(s) { return filtered.layout[s].map(function(e) { return e.id }) }
    ;["left", "center", "right"].forEach(function(s) {
      tucked.forEach(function(t) { check(vis(s).indexOf(t) === -1, t + " still on bar") })
    })
    check(vis("right").indexOf(id) !== -1, "drawer button must stay on the bar")
    check(JSON.stringify(bar) === before, "real config must not be mutated")
    check(filtered.id === id && filtered.position === bar.position, "other bar keys preserved")

    var drawerEntry = bar.layout.right.filter(function(e) { return e.id === id })[0]
    var settings = {}
    for (var k in drawerEntry) if (k !== "id") settings[k] = drawerEntry[k]
    var items = M.drawerItems(bar.layout, M.entryFromSettings(id, settings), id)
    same(items.map(function(i) { return i.id }), drawerEntry.items, "drawer order")
    check(items.every(function(i) { return i.inLayout }), "tucked widgets keep layout entries")

    same(M.itemList({ items: "omarchy.clock" }, id), ["omarchy.clock"], "string items")
    same(M.itemList({ items: [id, "a", "a", "", { id: "b" }] }, id), ["a", "b"], "dedupe/self/objects")
    same(M.itemList({}, id), [], "no items")
    var clock = M.drawerItems({ center: [{ id: "omarchy.clock", format: "HH:mm" }] }, { items: ["omarchy.clock", "x.missing"] }, id)
    same(clock[0], { id: "omarchy.clock", region: "center", settings: { format: "HH:mm" }, inLayout: true }, "settings lookup")
    check(clock[1].inLayout === false, "missing widget flagged")
    same(M.filteredBarConfig({ position: "top" }, id), { position: "top" }, "no layout")

    console.log("visible left:", vis("left"), "| center:", vis("center"), "| right:", vis("right"))
    console.log("drawer:", items.map(function(i) { return i.id + "@" + i.region }).join(", "))
    console.log("MODEL TESTS PASSED")
    Qt.exit(0)
  }
}
EOF
